    elif progression == 'geometric':
        if _advanced[0] == 0:
            return False
        ratio = _advanced[1] / _advanced[0]
        for i in range(2, len(_advanced)):
            if _advanced[i] / _advanced[i-1] != ratio:
                return False

    if zero_crossing:
        neg = False
        pos = False
        zero = False

        for x in _advanced:
            if x < 0:
                neg = True
            if pos:
                return False
            elif x > 0:
                pos = True
            if neg:
                return False
            else:
                zero = True
        if neg and pos:
            return False
        if not zero or not (neg and pos):
            return False

    if strict:
        if progression == 'arithmetic' and diff == 0:
            return False
        if progression == 'geometric' and ratio == 1:
            return False

    return True
```

This function returns `True` if a list `l` is monotonically increasing and `False` otherwise. It also checks if the progression is arithmetic or geometric. Plus, it has the flexibility to consider whether zero-crossing should be allowed and whether the progression should be strictly increasing.

