import torch

def calculate_overlap_area(rect1, rect2):
    if not isinstance(rect1, torch.Tensor) or not isinstance(rect2, torch.Tensor):
        raise ValueError("Input must be tensors")

    if rect1.shape != (4,) or rect2.shape != (4,):
        raise ValueError("Input must be tensors with shape (4,)")
    if rect1[2] <= 0 or rect1[3] <= 0 or rect2[2] <= 0 or rect2[3] <= 0:
